# Sequence: 1, 0, 1, 0, ...
a = []
for i in range(N):
    if (i + 1) % 2 != 0:
        a.append(1.0)
    else:
        a.append(0.0)

# Cyclic extension: a_{2025} = a_1, a_{2026} = a_2
a_cyclic = a + a[:2]

S = 0
for x in range(N):
    # a_x * a_{x+2}
    term = a[x] * a_cyclic[x+2]
    S += term

print(f"The calculated sum S for N={N} is: {S}")

